CREATE TABLE organisations(id uuid PRIMARY KEY,name text NOT NULL,branding jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY,email text UNIQUE NOT NULL,name text NOT NULL,password_hash text,is_service boolean NOT NULL DEFAULT false);
CREATE TABLE memberships(tenant_id uuid REFERENCES organisations(id),user_id uuid REFERENCES users(id),role text NOT NULL CHECK(role IN ('owner','admin','member','guest')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY,tenant_id uuid NOT NULL,user_id uuid NOT NULL,scopes text[],label text,expires_at timestamptz NOT NULL,FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id));
CREATE TABLE invitations(token_hash text PRIMARY KEY,tenant_id uuid REFERENCES organisations(id),email text NOT NULL,name text NOT NULL,role text NOT NULL CHECK(role IN ('admin','member','guest')),expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days');
CREATE TABLE resources(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES organisations(id),parent_id uuid,kind text NOT NULL CHECK(kind IN ('workspace','space','page','database','record')),title text NOT NULL CHECK(length(title) BETWEEN 1 AND 500),icon text NOT NULL DEFAULT '',position double precision NOT NULL DEFAULT 0,inherit_permissions boolean NOT NULL DEFAULT true,search_text text NOT NULL DEFAULT '',deleted_at timestamptz,created_by uuid REFERENCES users(id),updated_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,parent_id) REFERENCES resources(tenant_id,id),CHECK(parent_id IS DISTINCT FROM id),CHECK((kind='workspace' AND parent_id IS NULL) OR(kind<>'workspace' AND parent_id IS NOT NULL)));
CREATE INDEX resources_parent ON resources(tenant_id,parent_id,position,id);
CREATE INDEX resources_search ON resources USING gin(to_tsvector('simple',title||' '||search_text));
CREATE INDEX resources_modified ON resources(tenant_id,updated_at DESC);
CREATE TABLE acl(tenant_id uuid NOT NULL,resource_id uuid NOT NULL,principal_id text NOT NULL,level integer NOT NULL CHECK(level BETWEEN 0 AND 4),PRIMARY KEY(tenant_id,resource_id,principal_id),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE page_documents(tenant_id uuid NOT NULL,resource_id uuid NOT NULL,blocks jsonb NOT NULL DEFAULT '[]',plain_text text NOT NULL DEFAULT '',y_state bytea NOT NULL,revision integer NOT NULL DEFAULT 1,epoch integer NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,resource_id),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE page_versions(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,resource_id uuid NOT NULL,blocks jsonb NOT NULL,y_state bytea NOT NULL,revision integer NOT NULL,author_id uuid REFERENCES users(id),context text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id) ON DELETE CASCADE);
CREATE INDEX versions_resource ON page_versions(tenant_id,resource_id,created_at DESC);
CREATE TABLE databases(tenant_id uuid NOT NULL,resource_id uuid NOT NULL,properties jsonb NOT NULL,PRIMARY KEY(tenant_id,resource_id),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE database_records(tenant_id uuid NOT NULL,resource_id uuid NOT NULL,database_id uuid NOT NULL,values jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,resource_id),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,database_id) REFERENCES databases(tenant_id,resource_id));
CREATE INDEX records_database ON database_records(tenant_id,database_id);
CREATE INDEX records_values ON database_records USING gin(values);
CREATE TABLE database_views(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,database_id uuid NOT NULL,name text NOT NULL,config jsonb NOT NULL,FOREIGN KEY(tenant_id,database_id) REFERENCES databases(tenant_id,resource_id) ON DELETE CASCADE);
CREATE TABLE comments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,resource_id uuid NOT NULL,author_id uuid REFERENCES users(id),body text NOT NULL,block_id text,resolved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),edited_at timestamptz,FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE files(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,resource_id uuid NOT NULL,object_key text UNIQUE NOT NULL,name text NOT NULL,mime text NOT NULL,size bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE bookmarks(tenant_id uuid NOT NULL,user_id uuid NOT NULL,resource_id uuid NOT NULL,favourite boolean NOT NULL DEFAULT false,visited_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,user_id,resource_id),FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id));
CREATE TABLE notifications(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,user_id uuid NOT NULL,resource_id uuid NOT NULL,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id),FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id));
CREATE TABLE event_outbox(id uuid PRIMARY KEY,tenant_id uuid REFERENCES organisations(id),actor_id uuid,type text NOT NULL,resource_id uuid,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),dispatched_at timestamptz);
CREATE INDEX outbox_pending ON event_outbox(tenant_id,created_at) WHERE dispatched_at IS NULL;
CREATE TABLE webhook_subscriptions(id uuid PRIMARY KEY,tenant_id uuid REFERENCES organisations(id),url text NOT NULL,events text[] NOT NULL,secret_encrypted text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE webhook_deliveries(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,subscription_id uuid REFERENCES webhook_subscriptions(id),event_id uuid REFERENCES event_outbox(id),status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,next_at timestamptz NOT NULL DEFAULT now(),last_error text,UNIQUE(subscription_id,event_id));
CREATE TABLE audit_events(id uuid PRIMARY KEY,tenant_id uuid REFERENCES organisations(id),actor_id uuid,action text NOT NULL,resource_id uuid,request_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,user_id uuid NOT NULL,resource_id uuid NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',result jsonb,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,user_id) REFERENCES memberships(tenant_id,user_id));
DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='workspace_app') THEN CREATE ROLE workspace_app NOLOGIN NOSUPERUSER NOBYPASSRLS; END IF;END $$;
GRANT USAGE ON SCHEMA public TO workspace_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO workspace_app;
REVOKE UPDATE,DELETE ON audit_events FROM workspace_app;
REVOKE ALL ON schema_migrations FROM workspace_app;
DO $$ DECLARE tab text;key text;BEGIN
 FOREACH tab IN ARRAY ARRAY['organisations','memberships','invitations','resources','acl','page_documents','page_versions','databases','database_records','database_views','comments','files','bookmarks','notifications','event_outbox','webhook_subscriptions','webhook_deliveries','audit_events','jobs'] LOOP
 key:=CASE WHEN tab='organisations' THEN 'id' ELSE 'tenant_id' END;
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tab);
 EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(%I=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK(%I=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',tab,key,key);
 END LOOP;
END $$;
CREATE FUNCTION session_actor(p_hash text) RETURNS TABLE(tenant_id uuid,user_id uuid,role text,name text,email text,scopes text[],expires_at timestamptz) LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT s.tenant_id,s.user_id,m.role,u.name,u.email,s.scopes,s.expires_at FROM sessions s JOIN memberships m USING(tenant_id,user_id) JOIN users u ON u.id=s.user_id WHERE s.token_hash=p_hash AND s.expires_at>now() AND m.active; $$;
CREATE FUNCTION user_tenants(p_user uuid) RETURNS TABLE(tenant_id uuid,name text,role text) LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT o.id,o.name,m.role FROM memberships m JOIN organisations o ON o.id=m.tenant_id WHERE m.user_id=p_user AND m.active; $$;
CREATE FUNCTION worker_tenants() RETURNS TABLE(id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT id FROM organisations; $$;
CREATE FUNCTION invitation_context(p_hash text) RETURNS TABLE(tenant_id uuid,email text,name text,role text) LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT tenant_id,email,name,role FROM invitations WHERE token_hash=p_hash AND expires_at>now(); $$;
REVOKE ALL ON FUNCTION session_actor(text),user_tenants(uuid),worker_tenants(),invitation_context(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION session_actor(text),user_tenants(uuid),worker_tenants(),invitation_context(text) TO workspace_app;
